    {
      "n": "#19·04",
      "text": "This grey wool coat features a timeless English collar and a double-breasted silhouette. Crafted in a heathered texture, it drapes elegantly to offer warmth without bulk."
    },
    {
      "n": "#250·29",
      "text": "The beige maxi skirt has a sleek, fitted shape that flows to the floor with a subtle back slit, adding movement to your steps."
    },
    {
      "n": "#63·23",
      "text": "The grey cashmere sweater offers soft texture and relaxed fit, providing gentle coverage without restricting your comfort in the evening."
    },
    {
      "n": "#50·03",
      "text": "These beige heeled sandals have a low wedge platform and pebbled leather straps, balancing style with all-day comfort for dining out."
    },
    {
      "n": "#264·03",
      "text": "The creamy hobo bag is made of soft pebbled leather with an attached wide handle, offering a secure zip closure for your essentials."
    }
